import React, { useRef, useEffect } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls";
import axios from "axios";

const EarthScene = () => {
  const mountRef = useRef(null);

  useEffect(() => {
    const width = mountRef.current.clientWidth;
    const height = mountRef.current.clientHeight;

    // Scene
    const scene = new THREE.Scene();

    // Camera
    const camera = new THREE.PerspectiveCamera(45, width / height, 0.1, 2000);
    camera.position.set(0, 200, 400);

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(width, height);
    renderer.setPixelRatio(window.devicePixelRatio);
    mountRef.current.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;

    // Lights
    scene.add(new THREE.AmbientLight(0xffffff, 0.6));
    const dirLight = new THREE.DirectionalLight(0xffffff, 1);
    dirLight.position.set(5, 3, 5);
    scene.add(dirLight);

    const loader = new THREE.TextureLoader();

    // ---------- Earth ----------
    const earthTexture = loader.load("/textures/earth_atmos_2048.jpg");
    const earthRadius = 100;
    const earth = new THREE.Mesh(
      new THREE.SphereGeometry(earthRadius, 64, 64),
      new THREE.MeshPhongMaterial({ map: earthTexture })
    );
    const earthGroup = new THREE.Group();
    earthGroup.add(earth);
    scene.add(earthGroup);

    // Clouds
    const cloudTexture = loader.load("/textures/earth_clouds_1024.png");
    const clouds = new THREE.Mesh(
      new THREE.SphereGeometry(102, 64, 64),
      new THREE.MeshPhongMaterial({ map: cloudTexture, transparent: true, opacity: 0.11 })
    );
    earthGroup.add(clouds);

    // ---------- Stars Background ----------
    const starGeometry = new THREE.BufferGeometry();
    const starCount = 20000;
    const starPositions = new Float32Array(starCount * 3);
    for (let i = 0; i < starCount * 3; i++) {
      starPositions[i] = (Math.random() - 0.5) * 5000;
    }
    starGeometry.setAttribute("position", new THREE.BufferAttribute(starPositions, 3));
    const starMaterial = new THREE.PointsMaterial({ color: 0xffffff, size: 0.7 });
    const stars = new THREE.Points(starGeometry, starMaterial);
    scene.add(stars);

    // ---------- Live Active Satellites / Debris Group ----------
    const debrisGroup = new THREE.Group();
    scene.add(debrisGroup);

    // Shared geometry & material definitions for the live fleet mesh collection
    const satGeometry = new THREE.SphereGeometry(1.5, 8, 8);
    const satMaterial = new THREE.MeshStandardMaterial({ color: 0x00ffcc, flatShading: true });

    // Helper conversion math function to change geographic coordinates into 3D vectors
    const convertCoordsToVector = (lat, lon, alt) => {
      // Scale down altitude values natively so objects fit on screen comfortably
      const radius = earthRadius + (alt ? alt / 1000 : 15); 
      const phi = (90 - lat) * (Math.PI / 180);
      const theta = (lon + 180) * (Math.PI / 180);

      return new THREE.Vector3(
        -radius * Math.sin(phi) * Math.cos(theta),
        radius * Math.cos(phi),
        radius * Math.sin(phi) * Math.sin(theta)
      );
    };

    // Dynamic telemetry updates for general satellites
    const updateSatelliteFleet = async () => {
      try {
        const res = await axios.get("http://localhost:5000/api/debris");
        
        // Clear old meshes before plotting the newly computed telemetry points
        while(debrisGroup.children.length > 0){ 
          debrisGroup.remove(debrisGroup.children[0]); 
        }

        res.data.forEach((sat) => {
          const satMesh = new THREE.Mesh(satGeometry, satMaterial);
          satMesh.position.copy(convertCoordsToVector(sat.lat, sat.lon, sat.alt));
          debrisGroup.add(satMesh);
        });
      } catch (err) {
        console.error("Satellite fleet fetch telemetry exception:", err.message);
      }
    };

    // Sync satellite fleet positions updates periodically
    const satelliteInterval = setInterval(updateSatelliteFleet, 5000);
    updateSatelliteFleet();

    // ---------- ISS (International Space Station) ----------
    const issGeometry = new THREE.SphereGeometry(3.5, 16, 16);
    const issMaterial = new THREE.MeshStandardMaterial({ color: 0xff3300, emissive: 0xff1100 });
    const iss = new THREE.Mesh(issGeometry, issMaterial);
    scene.add(iss);

    const updateISS = async () => {
      try {
        const res = await axios.get("http://localhost:5000/iss");
        const { lat, lon, alt } = res.data;
        iss.position.copy(convertCoordsToVector(lat, lon, alt));
      } catch (err) {
        console.error("ISS fetch tracking error:", err.message);
      }
    };
    
    const issInterval = setInterval(updateISS, 5000);
    updateISS();

    // ---------- Animation Loop ----------
    const animate = () => {
      requestAnimationFrame(animate);

      earth.rotation.y += 0.0002;
      clouds.rotation.y += 0.0003;

      controls.update();
      renderer.render(scene, camera);
    };
    animate();

    // ---------- Window Resize ----------
    const handleResize = () => {
      const newWidth = mountRef.current.clientWidth;
      const newHeight = mountRef.current.clientHeight;
      renderer.setSize(newWidth, newHeight);
      camera.aspect = newWidth / newHeight;
      camera.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);

    return () => {
      window.removeEventListener("resize", handleResize);
      clearInterval(satelliteInterval);
      clearInterval(issInterval);
      if (mountRef.current && renderer.domElement) {
        mountRef.current.removeChild(renderer.domElement);
      }
    };
  }, []);

  return <div ref={mountRef} style={{ width: "100%", height: "100vh" }} />;
};

export default EarthScene;
